-- Atomic-dispatch scenarios: the dispatch marker, snapshot comparisons,
-- payment-account rechecks, and guard-semantics proofs. Runs after
-- manual_order_documents_redemption.sql in the same psql session (see
-- run-manual-order-document-tests.sh).
BEGIN;
CREATE OR REPLACE FUNCTION pg_temp.assert_true(ok boolean, label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %', label; END IF; END $$;

-- The dispatch marker atomically validates the rendered snapshot and records
-- dispatch start while holding the order row, closing the check-then-mark gap
-- between the sender's final read and the transport call.
UPDATE public.order_notification_outbox SET status = 'processing', locked_by = 'm2-worker', locked_at = now() WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt';
SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', 'Buyer', NULL, 100, 0, 0, 0, 0, 100, 'NGN', 'PAID', 'paid', NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'receipt', 3, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description, 'assurance_fee', oi.assurance_fee, 'line_id', oi.line_id, 'unit_code', oi.unit_code, 'line_extension_amount', oi.line_extension_amount, 'vat_category_code', oi.vat_category_code, 'vat_rate', oi.vat_rate, 'vat_amount', oi.vat_amount, 'sellers_item_id', oi.sellers_item_id) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000003'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '[]'::jsonb, 0, '[]'::jsonb, 'Fixture', 'Fixture Ltd', '1 Market St', '{"city": "Lagos"}'::jsonb, 'RC123', 'TIN123', 'registered', 7.5, NULL, NULL, NULL, NULL, 'fixture', '2026-09-30T09:00:00Z')->>'status' = 'marked'), 'fresh dispatch snapshot marks dispatch start');
SELECT pg_temp.assert_true((SELECT metadata->>'sent_document_kind' = 'receipt' FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt'), 'marked dispatch snapshots the sent kind');
UPDATE public.order_notification_outbox SET dispatch_started_at = NULL WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt';
-- Rendered branding + From name compare: a mid-dispatch branding edit aborts,
-- and the retry converges once it snapshots the new values.
UPDATE public.merchants SET email_sender_name = 'Shop Orders', logo_url = 'https://cdn.example.com/logo.png', brand_colors = '{"primary": "#000000"}'::jsonb WHERE id = '10000000-0000-4000-8000-000000000001';
SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', 'Buyer', NULL, 100, 0, 0, 0, 0, 100, 'NGN', 'PAID', 'paid', NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'receipt', 3, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description, 'assurance_fee', oi.assurance_fee, 'line_id', oi.line_id, 'unit_code', oi.unit_code, 'line_extension_amount', oi.line_extension_amount, 'vat_category_code', oi.vat_category_code, 'vat_rate', oi.vat_rate, 'vat_amount', oi.vat_amount, 'sellers_item_id', oi.sellers_item_id) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000003'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '[]'::jsonb, 0, '[]'::jsonb, 'Fixture', 'Fixture Ltd', '1 Market St', '{"city": "Lagos"}'::jsonb, 'RC123', 'TIN123', 'registered', 7.5, NULL, NULL, NULL, NULL, 'fixture', '2026-09-30T09:00:00Z', NULL, NULL, NULL)->>'status' = 'stale'), 'branding change aborts dispatch');
SELECT pg_temp.assert_true((SELECT public.mark_manual_document_dispatch_started((SELECT id FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt'), 'm2-worker', '10000000-0000-4000-8000-000000000002', 'buyer@example.com', 'Buyer', NULL, 100, 0, 0, 0, 0, 100, 'NGN', 'PAID', 'paid', NULL, 'pending', NULL, NULL, NULL, NULL, NULL, NULL, '10000000-0000-4000-8000-000000000010', NULL, NULL, 'receipt', 3, (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', oi.id, 'name', oi.name, 'quantity', oi.quantity, 'price', oi.price, 'variant_name', oi.variant_name, 'condition', oi.condition, 'item_description', oi.item_description, 'assurance_fee', oi.assurance_fee, 'line_id', oi.line_id, 'unit_code', oi.unit_code, 'line_extension_amount', oi.line_extension_amount, 'vat_category_code', oi.vat_category_code, 'vat_rate', oi.vat_rate, 'vat_amount', oi.vat_amount, 'sellers_item_id', oi.sellers_item_id) ORDER BY oi.id), '[]'::jsonb) FROM public.order_items AS oi WHERE oi.order_id = '10000000-0000-4000-8000-000000000003'), NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, '[]'::jsonb, 0, '[]'::jsonb, 'Fixture', 'Fixture Ltd', '1 Market St', '{"city": "Lagos"}'::jsonb, 'RC123', 'TIN123', 'registered', 7.5, NULL, NULL, NULL, NULL, 'fixture', '2026-09-30T09:00:00Z', 'Shop Orders', 'https://cdn.example.com/logo.png', '{"primary": "#000000"}'::jsonb)->>'status' = 'marked'), 're-snapshotted branding marks dispatch');
UPDATE public.order_notification_outbox SET dispatch_started_at = NULL WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt';
UPDATE public.merchants SET email_sender_name = NULL, logo_url = NULL, brand_colors = NULL WHERE id = '10000000-0000-4000-8000-000000000001';
-- Rendered invoice terms + fiscal references compare: a mid-dispatch terms
-- edit aborts, and the retry converges once it snapshots the new values.
UPDATE public.order_notification_outbox SET dispatch_started_at = now() WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt';
UPDATE public.orders SET payment_due_date = '2026-10-15', payment_terms = 'Net 30', buyer_reference = 'BR-1', firs_irn = 'IRN-1', firs_csid = 'CSID-1' WHERE id = '10000000-0000-4000-8000-000000000003';
SELECT pg_temp.assert_true((SELECT dispatch_started_at IS NULL FROM public.order_notification_outbox WHERE order_id = '10000000-0000-4000-8000-000000000003' AND event_type = 'manual_order_receipt'), 'invoice terms edit resets the in-flight marker');
